def word_count(text: str) -> int:
    return len(text.split())

cases = [
    "a b  c",           # múltiplos espaços
    "olá, mundo!",      # pontuação anexada
    "",                 # vazio
    "   ",              # apenas espaços
    "uma",              # uma palavra
    "olá, mundo! como vai?", # pontuação múltipla
    "  espaços  no  início e fim  ",
]
for c in cases:
    print(repr(c), "->", word_count(c))

